describe("#findAllChildDocumentIds", () => {
  test("should return empty array if no children", async () => {
    const team = await buildTeam();
    const user = await buildUser({ teamId: team.id });
    const collection = await buildCollection({
      userId: user.id,
      teamId: team.id,
    });
    const document = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      title: "test",
    });
    const results = await document.findAllChildDocumentIds();
    expect(results.length).toBe(0);
  });

  test("should return nested child document ids", async () => {
    const team = await buildTeam();
    const user = await buildUser({ teamId: team.id });
    const collection = await buildCollection({
      userId: user.id,
      teamId: team.id,
    });
    const document = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      title: "test",
    });
    const document2 = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      parentDocumentId: document.id,
      title: "test",
    });
    const document3 = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      parentDocumentId: document2.id,
      title: "test",
    });
    const results = await document.findAllChildDocumentIds();
    expect(results.length).toBe(2);
    expect(results[0]).toBe(document2.id);
    expect(results[1]).toBe(document3.id);
  });

  test("should apply where filter and prune unmatched branches", async () => {
    const team = await buildTeam();
    const user = await buildUser({ teamId: team.id });
    const collection = await buildCollection({
      userId: user.id,
      teamId: team.id,
    });
    const document = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      title: "test",
    });
    const publishedChild = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      parentDocumentId: document.id,
      title: "published",
    });
    // A draft (unpublished) child, with its own nested child.
    const draftChild = await buildDraftDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      parentDocumentId: document.id,
      title: "draft",
    });
    await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      parentDocumentId: draftChild.id,
      title: "published under draft",
    });

    const results = await document.findAllChildDocumentIds({
      publishedAt: {
        [Op.ne]: null,
      },
    });
    // Only the published child is returned; the draft branch is pruned so its
    // descendants are not traversed.
    expect(results).toEqual([publishedChild.id]);
  });

  test("should include soft-deleted children when paranoid is false", async () => {
    const team = await buildTeam();
    const user = await buildUser({ teamId: team.id });
    const collection = await buildCollection({
      userId: user.id,
      teamId: team.id,
    });
    const document = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      title: "test",
    });
    const child = await buildDocument({
      userId: user.id,
      teamId: team.id,
      collectionId: collection.id,
      parentDocumentId: document.id,
      title: "child",
    });
    await child.destroy();

    expect(await document.findAllChildDocumentIds()).toEqual([]);
    expect(
      await document.findAllChildDocumentIds(undefined, { paranoid: false })
    ).toEqual([child.id]);
  });
});

describe("#findAllParentDocumentIds", () => {
  test("should return empty array if there is no parent", async () => {
    const document = await buildDocument();

    expect(await document.findAllParentDocumentIds()).toEqual([]);
  });

  test("should return nested parent document ids in one query", async () => {
    const parent = await buildDocument();
    const child = await buildDocument({
      parentDocumentId: parent.id,
      collectionId: parent.collectionId,
      teamId: parent.teamId,
      userId: parent.createdById,
    });
    const grandchild = await buildDocument({
      parentDocumentId: child.id,
      collectionId: parent.collectionId,
      teamId: parent.teamId,
      userId: parent.createdById,
    });

    const query = sequelize.query.bind(sequelize);
    const spy = vi.spyOn(sequelize, "query").mockImplementation(query);
    try {
      const results = await grandchild.findAllParentDocumentIds();

      expect(results).toEqual([child.id, parent.id]);
      expect(spy).toHaveBeenCalledTimes(1);
    } finally {
      spy.mockRestore();
    }
  });

  test("should stop at soft-deleted parents unless paranoid is false", async () => {
    const parent = await buildDocument();
    const child = await buildDocument({
      parentDocumentId: parent.id,
      collectionId: parent.collectionId,
      teamId: parent.teamId,
      userId: parent.createdById,
    });
    const grandchild = await buildDocument({
      parentDocumentId: child.id,
      collectionId: parent.collectionId,
      teamId: parent.teamId,
      userId: parent.createdById,
    });
    await child.destroy();

    expect(await grandchild.findAllParentDocumentIds()).toEqual([]);
    expect(
      await grandchild.findAllParentDocumentIds({ paranoid: false })
